.data-table-page {
  padding: 24px;
  max-width: 960px;
  margin: 0 auto;
}

.data-table-title {
  margin: 0 0 16px;
}

.data-table {
  border: 1px solid var(--g-color-line-generic);
  border-radius: 12px;
  overflow: auto;
  background: var(--g-color-base-generic);
}

.data-table table {
  width: 100%;
  border-collapse: collapse;
}

.data-table th,
.data-table td {
  padding: 10px 16px;
  text-align: left;
  border-bottom: 1px solid var(--g-color-line-generic);
}

.data-table thead th {
  position: sticky;
  top: 0;
  z-index: 1;
  background: var(--g-color-base-generic-accent);
  color: var(--g-color-text-primary);
}

.data-table__cell_sortable {
  padding: 0;
}

.data-table__sort-button {
  display: flex;
  width: 100%;
  min-height: 42px;
  align-items: center;
  justify-content: flex-start;
  gap: 6px;
  padding: 10px 16px;
  border: 0;
  background: transparent;
  color: inherit;
  font: inherit;
  cursor: pointer;
}

.data-table__sort-button:disabled {
  cursor: default;
}

.data-table__arrow {
  opacity: 0.25;
}

.data-table__arrow_active {
  opacity: 1;
  color: var(--g-color-text-brand);
}

.data-table__row_selected {
  background: var(--g-color-base-selection);
}

.data-table__cell_selection {
  width: 44px;
  padding-right: 0;
}

.data-table-footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 16px;
  margin-top: 16px;
  flex-wrap: wrap;
}

.data-table-footer__selection {
  color: var(--g-color-text-secondary);
}
